/* plugin.min.js — Corrector ortográfico "languageTool" para TinyMCE.
 *
 * Funcionalidad:
 *   - Control "Corrector" en la barra de estado (junto al "Nº de palabras",
 *     por defecto) o botón en el toolbar (ui: 'toolbar'): abre un MODAL
 *     "palabra por palabra" (estilo Word) con sugerencias, Aceptar, Ignorar,
 *     Ignorar todas y navegación Anterior/Siguiente.
 *   - autoCheck: revisa con debounce mientras se escribe y subraya los
 *     errores (palabras bien escritas no se subrayan).
 *   - checkOnLoad: revisa el contenido inicial al cargar el editor.
 *   - Sin servidor: si el endpoint no está disponible (fallback: true), usa
 *     el diccionario español embebido (languageToolDict.es.js + Local).
 *
 * Configuración (cada clave dentro de languageTool: { ... }):
 *   enabled, autoCheck, checkOnLoad, buttonText, ui, toolbarPosition, language,
 *   endpoint, debounce, maxLength, timeoutMs, fallback
 *
 * NOTA: El botón se registra SIEMPRE de forma síncrona en el factory del
 * plugin, porque TinyMCE construye el toolbar durante la inicialización y un
 * addButton() tardío no se refleja en él. Los módulos (diccionario, modal...)
 * se cargan de forma asíncrona y los comportamientos se conectan cuando la
 * declaración está lista.
 */
(function (global) {
    "use strict";

    const PLUGIN_NAME = 'languageTool';
    // Lápiz simple (estilo stroke, monocromo como los iconos de TinyMCE)
    const LT_ICON_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">' +
        '<g fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.7">' +
        '<path d="M17 3a2.828 2.828 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5L17 3z"/>' +
        '</g></svg>';
    const MODULE_FILES = [
        'languageToolDict.es.js',
        'languageToolExtra.es.js',
        'languageToolLocal.js',
        'languageToolMapper.js',
        'languageToolApi.js',
        'languageToolUi.js'
    ];
    const CSS_ID = 'languageToolPluginCss';

    let PLUGIN_BASE = '';
    let modulesStarted = false;
    let cssLoaded = false;
    let registered = false;

    /* Base del plugin calculada desde la URL del propio script (eval-time),
       para no depender de la ruta `url` que pasa TinyMCE en el factory. */
    const TOP_BASE = (function () {
        if (global.document && global.document.currentScript) {
            const src = global.document.currentScript.src;
            if (src && typeof src === 'string') {
                const pos = src.lastIndexOf('plugin.min.js');
                if (pos > 0) return src.slice(0, pos);
                const slash = src.lastIndexOf('/');
                if (slash > 0) return src.slice(0, slash + 1);
            }
        }
        return null;
    })();

    /* ---------- carga de módulos ---------- */

    function injectCssIntoPage() {
        if (cssLoaded) return;
        cssLoaded = true;
        if (global.document.getElementById(CSS_ID)) return;
        const link = global.document.createElement('link');
        link.id = CSS_ID;
        link.rel = 'stylesheet';
        link.href = PLUGIN_BASE + 'languageTool.css';
        global.document.head.appendChild(link);
    }

    function loadScript(src, onload, onerror) {
        if (global.LanguageTool && global.LanguageTool._rn && global.LanguageTool._rn[src]) {
            onload();
            return;
        }
        const s = global.document.createElement('script');
        s.async = false;
        s.src = src;
        s.onload = function () {
            global.LanguageTool = global.LanguageTool || {};
            global.LanguageTool._rn = global.LanguageTool._rn || {};
            global.LanguageTool._rn[src] = true;
            onload();
        };
        s.onerror = function () {
            onerror(new Error('No se pudo cargar ' + src));
        };
        global.document.head.appendChild(s);
    }

    function loadModule(index) {
        if (index >= MODULE_FILES.length) {
            warmDict();
            return;
        }
        loadScript(PLUGIN_BASE + MODULE_FILES[index], function () {
            loadModule(index + 1);
        }, function (err) {
            if (global.console) console.error('[languageTool]', err && err.message);
        });
    }

    /* Estado cálido del diccionario: el bootstrap (Dict.load) es diminuto; los
       4 MB de palabras viven en languageToolDict.es.chunk.js y se cargan aquí
       de forma ASÍNCRONA (script tag, compatible file://). */
    function warmDict() {
        try {
            const ns = nsAll();
            if (ns.Local && ns.Local.setDictUrl) {
                ns.Local.setDictUrl(PLUGIN_BASE + 'languageToolDict.es.chunk.js');
                ns.Local.ensureDict();
            }
        } catch (e) { if (global.console) console.error('[languageTool] warmDict', e); }
    }

    function ensureModules() {
        if (modulesStarted) return;
        modulesStarted = true;
        injectCssIntoPage();
        loadModule(0);
    }

    function nsReady() {
        return global.LanguageTool &&
            global.LanguageTool.Dict &&
            global.LanguageTool.Local &&
            global.LanguageTool.Mapper &&
            global.LanguageTool.UI &&
            global.LanguageTool.Api;
    }

    function whenReady(cb) {
        let tries = 0;
        (function poll() {
            tries++;
            if (nsReady()) cb();
            else if (tries < 600) setTimeout(poll, 50);
            else if (global.console) console.error('[languageTool] No se pudieron cargar los módulos del corrector.');
        })();
    }

    /* ---------- configuración ---------- */

    function readConfig(editor, url) {
        let cfg = {};
        try {
            if (editor.options && editor.options.register) {
                editor.options.register('languageTool', { processor: 'object' });
            }
            if (editor.options && editor.options.get) {
                const v = editor.options.get('languageTool');
                if (v && typeof v === 'object') cfg = v;
            }
            if (!cfg.enabled && editor.settings && editor.settings['languageTool']) {
                cfg = Object.assign({}, editor.settings['languageTool'], cfg);
            }
        } catch (e) {
            cfg = {};
        }
        void url;
        return {
            enabled: cfg.enabled === true,
            autoCheck: cfg.autoCheck === true,
            checkOnLoad: cfg.checkOnLoad === true,
            fallback: cfg.fallback !== false,
            ui: cfg.ui || 'statusbar',
            buttonText: cfg.buttonText || 'Corrector',
            language: cfg.language || 'es',
            endpoint: cfg.endpoint || '',
            debounce: cfg.debounce != null ? cfg.debounce : 900,
            maxLength: cfg.maxLength != null ? cfg.maxLength : 200000,
            timeoutMs: cfg.timeoutMs != null ? cfg.timeoutMs : 15000
        };
    }

    function notify(editor, text, type) {
        try {
            if (editor.notificationManager) {
                editor.notificationManager.open({
                    text: text,
                    type: type || 'info',
                    timeout: 4000
                });
                return;
            }
        } catch (e) { /* noop */ }
        if (global.console) console.log('[languageTool]', text);
    }

    /* ---------- estado ---------- */

    function createState(cfg) {
        return {
            cfg: cfg,
            matches: [],
            currentText: '',
            modalIndex: 0,
            modal: null,
            usingLocal: false,
            fallbackNotified: false,
            reviewing: false,
            applying: false,
            buttonApi: null,
            ignoredKeys: new Set(),
            ignoreWords: new Set()
        };
    }

    function keyOf(m) { return (m.offset || 0) + ':' + (m.length || 0) + ':' + (m.ruleId || ''); }

    function wordAt(state, m) {
        return state.currentText.slice(m.offset || 0, (m.offset || 0) + (m.length || 0));
    }

    function filterMatches(state, matches) {
        return matches.filter(function (m) {
            if (state.ignoredKeys.has(keyOf(m))) return false;
            if (state.ignoreWords.has(wordAt(state, m).toLowerCase())) return false;
            return true;
        });
    }

    /* ---------- ciclo de revisión ---------- */

    function performCheck(editor, state, text) {
        const ns = nsAll();
        const runLocal = function () {
            return ns.Local.check(text, state.cfg.language)
                .then(function (m) { return { matches: m, provider: 'local' }; });
        };
        if (!text.trim()) return Promise.resolve({ matches: [], provider: null });
        if (text.length > state.cfg.maxLength) return Promise.resolve({ matches: [], provider: null, skipped: true });
        if (state.usingLocal || !state.cfg.endpoint) return runLocal();
        return ns.Api.requestCheck({
            endpoint: state.cfg.endpoint,
            text: text,
            language: state.cfg.language,
            timeoutMs: state.cfg.timeoutMs
        }).then(function (res) {
            state.usingLocal = false;
            return { matches: ns.Api.normalize(res), provider: 'api' };
        }, function (err) {
            state.usingLocal = true;
            if (state.cfg.fallback) {
                if (global.console && !state.fallbackNotified) {
                    console.warn('[languageTool] Endpoint no disponible; usando corrector local embebido.', err);
                }
                state.fallbackNotified = true;
                return runLocal();
            }
            return { matches: [], provider: 'api' };
        });
    }

    function markErrors(editor, state, text) {
        return performCheck(editor, state, text).then(function (result) {
            state.currentText = text;
            state.matches = filterMatches(state, result.matches);
            const n = nsAll().Mapper.markMatches(editor, state.matches);
            return { matches: state.matches, n: n, provider: result.provider, skipped: !!result.skipped };
        });
    }

    /* ---------- acciones del modal ---------- */

    function afterMutate(editor, state) {
        nsAll().Mapper.markMatches(editor, state.matches);
        if (state.modal) {
            state.modalIndex = Math.min(Math.max(0, state.modalIndex), Math.max(0, state.matches.length - 1));
            state.modal.render();
            if (state.matches.length === 0) {
                state.modal.close();
                notify(editor, 'No se han encontrado más errores.', 'info');
            }
        }
    }

    function removeMatch(state, key) {
        const idx = state.matches.findIndex(function (m) { return keyOf(m) === key; });
        if (idx >= 0) {
            state.matches.splice(idx, 1);
            if (idx < state.modalIndex && state.modalIndex > 0) state.modalIndex--;
        }
    }

function applySuggestion(editor, state, match, replacement) {
    // Guard: evitar clics dobles. Mientras haya un reemplazo+re-chequeo
    // pendiente (markErrors es asíncrono), un segundo replaceAt usaría un
    // offset ya inválido (el texto cambió de longitud).
    if (state.applying) return;
    const prevIndex = state.modalIndex;
    state.applying = true;

    nsAll().Mapper.replaceAt(editor, match.offset || 0, match.length || 0, replacement);
    const text = nsAll().Mapper.extractText(editor).text;
    markErrors(editor, state, text).then(function (res) {
        state.applying = false;
        if (state.modal) {
            // Tras corregir el error índice "prevIndex", la lista nueva deja el
            // siguiente error en esa misma posición (el corregido ya no está;
            // el resto se ha desplazado un puesto). Si el reemplazo se vuelve a
            // marcar (sugerencia no válida), reaparece en prevIndex y el usuario
            // lo ve de nuevo. El "siguiente" lo resuelve el render contra el
            // texto REAL (state.currentText), no contra un snapshot antiguo.
            state.modalIndex = Math.max(0, Math.min(Math.max(0, res.matches.length - 1), prevIndex));
            state.modal.render();
            if (res.matches.length === 0) {
                state.modal.close();
                notify(editor, 'No se han encontrado más errores.', 'info');
            }
        }
    })["catch"](function (err) {
        // Nunca dejar el modal congelado: el guard anti-doble-click usa
        // state.applying, y un re-check fallido lo resetea para poder seguir
        // corrigiendo el resto de errores sin recargar.
        state.applying = false;
        if (global.console && console.warn) console.warn('languageTool: error tras aplicar sugerencia', err);
        if (state.modal) state.modal.render();
    });
}

    function ignoreError(editor, state, match) {
        state.ignoredKeys.add(keyOf(match));
        removeMatch(state, keyOf(match));
        afterMutate(editor, state);
    }

    function ignoreAllError(editor, state, match) {
        const word = wordAt(state, match).toLowerCase();
        state.ignoreWords.add(word);
        state.matches = state.matches.filter(function (m) {
            return wordAt(state, m).toLowerCase() !== word;
        });
        afterMutate(editor, state);
    }

    /* ---------- modal ---------- */

    function openModal(editor, state, index) {
        if (state.modal) state.modal.close();
        state.modalIndex = Math.max(0, Math.min(index || 0, Math.max(0, state.matches.length - 1)));
        const ns = nsAll();
        const ui = ns.UI.openModal({
            editor: editor,
            text: function () { return state.currentText; },
            matches: function () { return state.matches; },
            index: function () { return state.modalIndex; },
            setIndex: function (i) { state.modalIndex = i; },
            onApply: function (m, r) { applySuggestion(editor, state, m, r); },
            onIgnore: function (m) { ignoreError(editor, state, m); },
            onIgnoreAll: function (m) { ignoreAllError(editor, state, m); },
            onClose: function () { state.modal = null; }
        });
        state.modal = ui;
        return ui;
    }

    function review(editor, state) {
        if (!nsReady()) {
            ensureModules();
            notify(editor, 'Cargando corrector…', 'info');
            return;
        }
        if (state.reviewing) return;
        state.reviewing = true;
        nsAll().UI.setButtonState(state.buttonApi, true, state.cfg.buttonText);
        const text = nsAll().Mapper.extractText(editor).text;
        markErrors(editor, state, text).then(function (res) {
            state.reviewing = false;
            nsAll().UI.setButtonState(state.buttonApi, false, state.cfg.buttonText);
            if (!state.matches.length) {
                notify(editor, res.skipped
                    ? 'El texto supera el límite de caracteres para la revisión.'
                    : 'No se han encontrado errores de ortografía.', 'info');
                return;
            }
            openModal(editor, state, 0);
        });
    }

    /* ---------- comportamientos (requieren módulos cargados) ---------- */

    function setupBehaviors(editor, state) {
        const ns = nsAll();
        const Mapper = ns.Mapper;

        if (state.cfg.checkOnLoad) {
            const runInitialCheck = function () {
                const text = Mapper.extractText(editor).text;
                markErrors(editor, state, text);
            };
            if (editor.initialized) runInitialCheck();
            else editor.on('init', runInitialCheck);
        }

        if (state.cfg.autoCheck) {
            let timer = null;
            editor.on('input', function () {
                clearTimeout(timer);
                timer = setTimeout(function () {
                    const text = Mapper.extractText(editor).text;
                    markErrors(editor, state, text);
                }, state.cfg.debounce);
            });
        }

        editor.on('click', function (e) {
            let node = e && e.target;
            while (node && node.nodeType === 1) {
                if (node.className && String(node.className).split(/\s+/).indexOf('lt-marker') !== -1) break;
                node = node.parentNode;
            }
            if (!node || node === editor.getDoc() || node === editor.getBody()) return;
            const offset = parseInt(node.getAttribute && node.getAttribute('data-lt-offset') || '-1', 10);
            const length = parseInt(node.getAttribute && node.getAttribute('data-lt-length') || '0', 10);
            const rule = node.getAttribute && node.getAttribute('data-lt-rule') || '';
            const idx = state.matches.findIndex(function (m) {
                return (m.offset | 0) === offset && (m.length | 0) === length && (!rule || m.ruleId === rule);
            });
            if (idx >= 0) openModal(editor, state, idx);
        });
    }

    /* ---------- control de la barra de estado (junto al nº de palabras) ---------- */

    let statusBarCssInjected = false;
    function injectStatusBarCss() {
        if (statusBarCssInjected || !global.document) return;
        statusBarCssInjected = true;
        const style = global.document.createElement('style');
        style.textContent =
            '.tox .tox-statusbar__lt-corrector{align-items:center;background:none;border:0;border-radius:3px;' +
            'box-shadow:none;color:inherit;cursor:pointer;display:inline-flex;flex:0 0 auto;font:inherit;' +
            'gap:4px;line-height:1;margin-left:1ch;padding:2px 4px;text-transform:none}' +
            '.tox .tox-statusbar__lt-corrector:hover{color:rgba(34,47,62,1)}' +
            '.tox .tox-statusbar__lt-corrector--checking{opacity:.5;pointer-events:none}' +
            '.tox .tox-statusbar__lt-corrector svg{height:14px;width:14px}';
        (global.document.head || global.document.documentElement).appendChild(style);
    }

    // Añade un botón "Corrector" en la barra de estado, justo después del
    // contador de palabras (el selector de tamaño es del toolbar; aquí el
    // control vive junto al "Nº de palabras" que pinta TinyMCE).
    function mountStatusBarControl(editor, state, cfg) {
        if (!global.document) return;
        injectStatusBarCss();
        const doc = global.document;
        let tries = 0;

        const attempt = function () {
            if (state.statusbarMounted) return true;
            const container = editor.getContainer ? editor.getContainer() : null;
            if (!container) return false;
            const statusbar = container.querySelector('.tox-statusbar');
            if (!statusbar) return false;
            const right = statusbar.querySelector('.tox-statusbar__right-container') || statusbar;
            const wordcount = right.querySelector('.tox-statusbar__wordcount');

            const icon = doc.createElement('span');
            icon.className = 'tox-statusbar__lt-icon';
            icon.innerHTML = LT_ICON_SVG.replace('<svg ', '<svg width="14" height="14" ');
            const label = doc.createElement('span');
            label.className = 'tox-statusbar__lt-label';
            label.textContent = cfg.buttonText;

            const btn = doc.createElement('button');
            btn.type = 'button';
            btn.className = 'tox-statusbar__lt-corrector';
            btn.title = 'Corregir ortografía';
            btn.appendChild(icon);
            btn.appendChild(label);
            btn.addEventListener('click', function () { review(editor, state); });

            if (wordcount && wordcount.nextSibling) right.insertBefore(btn, wordcount.nextSibling);
            else right.appendChild(btn);

            state.statusbarControl = btn;
            state.buttonApi = {
                setDisabled: function (d) { btn.classList.toggle('tox-statusbar__lt-corrector--checking', !!d); },
                setText: function (t) { label.textContent = t; }
            };
            editor.on('remove', function () { if (btn && btn.parentNode) btn.parentNode.removeChild(btn); });
            state.statusbarMounted = true;
            return true;
        };

        if (editor.initialized) { if (attempt()) return; }
        else editor.on('init', function () { attempt(); });

        // La barra de estado se pinta durante la inicialización; reintentos
        // para no perderla si el theme tarda un poco.
        const timer = setInterval(function () {
            if (state.statusbarMounted || ++tries > 100) clearInterval(timer);
            else attempt();
        }, 50);
    }

    /* ---------- registro ---------- */

    function nsAll() { return global.LanguageTool || {}; }

    function register() {
        if (registered || !global.tinymce) return;
        registered = true;
        global.tinymce.PluginManager.add(PLUGIN_NAME, function (editor, url) {
            // Resolver la carpeta del plugin. Prioridad: URL real del script;
            // si no (carga minificada/empaquetada), normalizar la de TinyMCE.
            if (TOP_BASE) {
                PLUGIN_BASE = TOP_BASE;
            } else if (url) {
                let u = String(url).replace(/\/+$/, '');
                u = u.slice(0, u.lastIndexOf('/') + 1) + 'languageTool';
                PLUGIN_BASE = u + '/';
            }
            // Inyectar plugins y arrancar la carga de módulos
            ensureModules();

            // Configuración (no requiere módulos)
            const cfg = readConfig(editor, url);
            const state = createState(cfg);

            if (cfg.enabled) {
                if (cfg.ui === 'toolbar') {
                    // Botón en el toolbar (modo clásico).
                    try { editor.ui.registry.addIcon('lt-corrector', LT_ICON_SVG); } catch (e) { /* noop */ }
                    editor.ui.registry.addButton(PLUGIN_NAME, {
                        text: cfg.buttonText,
                        icon: 'lt-corrector',
                        tooltip: 'Corregir ortografía',
                        onAction: function () { review(editor, state); },
                        onSetup: function (api) {
                            state.buttonApi = api;
                            return function () { state.buttonApi = null; };
                        }
                    });
                } else {
                    // Control en la barra de estado (junto al "Nº de palabras").
                    editor.on('init', function () { mountStatusBarControl(editor, state, cfg); });
                }
            }

            // Comportamientos que requieren los módulos del corrector
            whenReady(function () {
                if (cfg.enabled) setupBehaviors(editor, state);
            });

            return {};
        });
    }

    register();
})(typeof window !== "undefined" ? window : globalThis);